// Turns the form submission into the fields the rest of the workflow uses.
// Field names come from Settings, because every Contact Form 7 form names its own fields.
const settings = $('Settings').first().json;
const form = $input.first().json.body || {};

// Checkboxes and multi-selects arrive as arrays. Anything nested is shown as short JSON.
const one = (value) => (value !== null && typeof value === 'object' ? JSON.stringify(value) : String(value ?? ''));
const text = (value) => (Array.isArray(value) ? value.map(one).join(', ') : one(value)).trim().slice(0, 500);

const email = text(form[settings.email_field]).toLowerCase();
const message = text(form[settings.message_field]);

// One "Your name" field: first word is the first name, the rest is the last name.
const nameParts = text(form[settings.name_field]).split(/\s+/).filter(Boolean);
const first_name = nameParts[0] || '';
const last_name = nameParts.slice(1).join(' ');

const form_label = text(form.form_title) || (form.form_id ? 'form #' + form.form_id : '');
const page_url = text(form.page_url);

// Everything else the form sent (phone, subject, consent boxes) goes into the alerts.
const known = [settings.email_field, settings.name_field, settings.message_field, 'form_id', 'form_title', 'page_url'];
// Field names become labels: "your-phone" reads as "Phone".
const label = (key) => {
  const words = key.replace(/^your-/, '').replace(/[-_]+/g, ' ').trim();
  return words.charAt(0).toUpperCase() + words.slice(1);
};
const other_fields = Object.keys(form)
  .filter((key) => !known.includes(key) && text(form[key]) !== '')
  .map((key) => label(key) + ': ' + text(form[key]));

const lines = [
  'From: ' + [first_name, last_name].join(' ').trim() + (email ? ' <' + email + '>' : ' (no email)'),
  ...other_fields,
  message ? 'Message: ' + message : '',
  page_url ? 'Page: ' + page_url : '',
].filter(Boolean);

const heading = form_label ? 'New submission on ' + form_label : 'New form submission';

return [{ json: { email, first_name, last_name, message, heading, page_url, summary: lines.join('\n') } }];

