      "maximum": 5,
      "description": "How likely the visitor is to buy. 1: support, spam or no buying intent. 2: vague interest. 3: asks about prices or a service without details. 4: a clear need plus a budget or a timeline. 5: a clear need, a budget and a timeline, and wants to talk now."
    },
    "summary": {
      "type": "string",
      "description": "One sentence in English on what the visitor wants."
    }
  },
  "required": [
    "category",
    "score",
    "summary"
  ]
}

