// Adds the model's verdict to the lead. If the model failed or answered outside the schema,
// the lead goes to sales unscored, so a model outage never loses a lead.
const settings = $('Settings').first().json;
const lead = $('Lead Fields').first().json;
const answer = $input.first().json;
const verdict = answer.output || {};

// No email and no message means the field names do not match the form. Send it to sales as a
// setup warning instead of letting the model call it spam, where it would disappear.
const empty = !lead.email && !lead.message;
const scored = !empty && ['lead', 'support', 'spam'].includes(verdict.category);
const score = Math.min(5, Math.max(1, Math.round(Number(verdict.score) || 1)));
const failure = answer.error ? (answer.error.message || answer.error) : 'no usable answer';

// HubSpot notes are HTML, so the visitor's text is escaped before it goes in.
const html = (value) => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ai_summary = empty
  ? 'Not scored: no email and no message arrived. Check the field names in Settings and in WordPress.'
  : scored ? String(verdict.summary || '').trim() : 'Not scored (' + failure + ')';
const note_html = [
  '<p><strong>' + html(lead.heading) + '</strong></p>',
  '<p>' + html(scored ? 'Score ' + score + '/5: ' + ai_summary : ai_summary) + '</p>',
  '<p>' + lead.summary.split('\n').map(html).join('<br>') + '</p>',
].join('');

return [{
  json: {
    ...lead,
    category: scored ? verdict.category : 'lead',
    score: scored ? score : null,
    is_hot: scored && score >= Number(settings.hot_score),
    ai_summary,
    note_html,
  },
}];

// Builds the sales alert from whichever path the lead took: no email, saved, or rejected by HubSpot.
const settings = $('Settings').first().json;
const lead = $('Lead Verdict').first().json;

const verdict = lead.score === null
  ? ':grey_question: ' + lead.ai_summary
  : (lead.is_hot ? ':fire: Hot lead ' : ':bust_in_silhouette: Lead ') + lead.score + '/5: ' + lead.ai_summary;

let crm = ':warning: No email address, so it was not saved to HubSpot';
if ($('Save to HubSpot').isExecuted) {
  const contact = $('Save to HubSpot').first().json;
  crm = contact.vid
    ? (contact.isNew ? ':new: New contact' : ':repeat: Returning contact') + ' in HubSpot: '
      + settings.hubspot_app_url + '/contacts/' + contact['portal-id'] + '/record/0-1/' + contact.vid
    : ':warning: HubSpot rejected this lead: ' + (contact.error?.message || contact.error);
}
if ($('Add Note').isExecuted && $('Add Note').first().json.error) {
  const error = $('Add Note').first().json.error;
  crm += '\n:warning: The note was not added: ' + (error.message || error);
}

return [{ json: { text: [verdict, crm, '*' + lead.heading + '*', lead.summary].join('\n') } }];
